/* ===== data8e: topical questions (Topics 9 and 10): metals, water, nitrogen/fertilisers, CO2/methane, air and rust. Wording from the teacher's topical question sets; answers are the hub's own, not an official mark scheme ===== */
const X5_S=(f,n)=>"Cambridge IGCSE 0620 topical question, "+f+", Question "+n;
const X5_W=n=>X5_S("Water",n);
U[9].pp.push(
P("Water treatment: filtration and chlorination",2,"<p>Filtration and chlorination are two stages in water treatment.</p><p>State the purpose of each stage. [2]</p>",["filtration (1): removes insoluble solids / suspended particles from the water.","chlorination (1): kills bacteria / microbes so that the water is safe to drink."],X5_W(1)),
P("Testing for water and the boiling point of water",3,"<p>A student uses anhydrous copper(II) sulfate to test for the presence of water.</p><ol type='a'><li>What colour change is seen if water is present?<br>from ........ to ........ [2]</li><li>The purity of a sample of water can be assessed by measuring its boiling point.<br>How is the boiling point of water affected by impurities? [1]</li></ol>",["(a) from white (1) to blue (1).","(b) The boiling point is raised (above 100 °C) / the boiling occurs over a range of temperatures (1)."],X5_W(2)),
P("Stages in water treatment",5,"<p>The diagram shows some of the stages in water treatment.</p><p><b>impure water → aeration tank (air in) → filter → mixing tank (chlorine in) → purified water</b></p><ol type='a'><li>Air is blown through the aeration tank.<br>Name the <b>two</b> gases that make up most of the air. [2]</li><li>After aeration, the water still contains large insoluble particles.<br>The filter is made up of fine sand and stones.<br>Explain how the filter helps purify the water. [2]</li><li>Explain why chlorine is used in water treatment. [1]</li></ol>",["(a) nitrogen (1) and oxygen (1).","(b) The insoluble particles are too large to pass through the gaps between the sand and stones (1), so they are trapped / stay behind in the filter while the water passes through (1).","(c) Chlorine kills bacteria / microorganisms (1)."],X5_W(3)),
P("Killing bacteria in drinking water",1,"<p>The following are the symbols and formulae of some elements and compounds.</p><p>Ar &nbsp; Ca(OH)~2~ &nbsp; Cl~2~ &nbsp; CO~2~ &nbsp; Cu &nbsp; Fe &nbsp; SO~2~ &nbsp; V~2~O~5~</p><p>State which element or compound in the list is used to kill bacteria in drinking water. [1]</p>",["Cl~2~ (1), chlorine."],X5_W(4)),
P("Copper compound used to test for water",3,"<p>A compound of copper can be used to test for water.</p><ol type='a'><li>State the full name of this compound of copper. [1]</li><li>State the colour change that occurs when water is added to this compound of copper.<br>from ........ to ........ [2]</li></ol>",["(a) anhydrous copper(II) sulfate (1).","(b) from white (1) to blue (1)."],X5_W(5)),
P("Cobalt(II) chloride and water",2,"<p>Cobalt is a transition element. Anhydrous cobalt(II) chloride is used to test for water.</p><p>State the colour change that occurs when water is added to anhydrous cobalt(II) chloride.<br>from ........ to ........ [2]</p>",["from blue (1) to pink (1)."],X5_W(6)),
P("Describe a chemical test for water",2,"<p>Describe a chemical test for water.</p><p>test ........<br>observation ........ [2]</p>",["test: add the liquid to anhydrous copper(II) sulfate (or anhydrous cobalt(II) chloride) (1).","observation: white anhydrous copper(II) sulfate turns blue (or blue cobalt(II) chloride turns pink) (1)."],X5_W(7)),
P("Anhydrous copper(II) sulfate test",2,"<p>Anhydrous copper(II) sulfate is used to test for water.</p><p>State the colour change in this test.<br>from ........ to ........ [2]</p>",["from white (1) to blue (1)."],X5_W(8)),
P("Anhydrous cobalt(II) chloride test",2,"<p>Anhydrous cobalt(II) chloride is used to test for water.</p><p>State the colour change in this test.<br>from ........ to ........ [2]</p>",["from blue (1) to pink (1)."],X5_W(9)),
P("Separating a solution from an undissolved solid",1,"<p>Give the name of the process that is used to separate an aqueous solution from an undissolved solid. [1]</p>",["Filtration (1)."],X5_W(10))
);

/* ---------- Nitrogen and fertilisers ---------- */
const X5_N=n=>X5_S("Nitrogen and fertilisers",n);
const X5_Q4=TBL(["Substance","Structure shown"],[["A","SO~2~: a sulfur atom double-bonded to two oxygen atoms"],["B","A lattice of NH~4~^+^ ions and Cl^−^ ions in alternating rows"],["C","N≡N: two nitrogen atoms joined by a triple bond"],["D","NH~3~: a nitrogen atom single-bonded to three hydrogen atoms"],["E","O=C=O: a carbon atom double-bonded to two oxygen atoms"]],520);
U[9].pp.push(
P("Haber process: why not a lower temperature or a higher pressure?",2,"<p>Ammonia is produced in the Haber process.</p><p>The equation for the reaction is shown.</p><p style='text-align:center'>N~2~(g) + 3H~2~(g) → 2NH~3~(g)</p><p>In the Haber process, a temperature of 450 °C and a pressure of 200 atmospheres are used in the presence of finely-divided iron.</p><p>A larger equilibrium yield of ammonia would be produced if a lower temperature and a higher pressure are used.</p><p>Explain why a lower temperature and a higher pressure are <b>not</b> used.</p><p>lower temperature ........<br>higher pressure ........ [2]</p>",["lower temperature (1): the rate of reaction would be too slow (even though the yield is higher).","higher pressure (1): very high pressure needs expensive, strong equipment and a lot of energy, and is a safety risk / costs too much."],X5_N(1)),
P("Lime and ammonium fertilisers",3,"<p>Farmers fertilise soil by adding compounds containing ammonium salts.</p><p>Explain why adding lime to fertilised soil may cause a loss of nitrogen from the soil. [3]</p>",["Lime (calcium hydroxide / calcium oxide) is a base / alkali (1).","It reacts with ammonium salts (1) to form ammonia gas (1), which escapes from the soil, so the nitrogen is lost."],X5_N(2)),
P("Ammonium sulfate reacts with sodium hydroxide",2,"<p>Ammonium salts react with alkalis. For example:</p><p style='text-align:center'>ammonium sulfate + sodium hydroxide → sodium sulfate + ammonia + water</p><p>Use this information to explain why adding slaked lime to fields which have fertilisers spread on them may result in loss of nitrogen. [2]</p>",["Slaked lime is an alkali, so it reacts with the ammonium salts in the fertiliser (1).","This makes ammonia gas, which escapes from the soil, so the nitrogen is no longer available to plants (1)."],X5_N(3)),
P("Which structure is a fertiliser?",1,"<p>The diagram shows the structures of five substances, <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b> and <b>E</b>.</p>"+X5_Q4+"<p>Which structure, <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b> or <b>E</b> is a compound which is used as a fertiliser? [1]</p>",["B (1): it is ammonium chloride, an ammonium salt that supplies nitrogen."],X5_N(4)),
P("Why slaked lime is not added with ammonium fertilisers",2,"<p>Many fertilisers contain ammonium salts.</p><p>Explain why farmers do <b>not</b> add calcium hydroxide (slaked lime) to the soil at the same time as fertilisers containing ammonium salts. [2]</p>",["Calcium hydroxide is an alkali and reacts with ammonium salts to release ammonia gas (1).","The ammonia escapes, so the nitrogen is lost and the fertiliser is wasted / plants cannot use it (1)."],X5_N(5)),
P("Haber process: conditions and equation",5,"<p>Give the essential reaction conditions and write a chemical equation for the reaction occurring in the Haber process.</p><p>chemical equation: ........<br>reaction conditions: ........ [5]</p>",["equation: N~2~ + 3H~2~ ⇌ 2NH~3~. Correct formulae (1), balanced with reversible arrow (1).","temperature about 450 °C (1).","pressure about 200 atmospheres (1).","iron catalyst (1)."],X5_N(6)),
P("Obtaining nitrogen for the Haber process",2,"<p>Nitrogen can be converted into ammonia by the Haber process.</p><p>Describe how nitrogen is obtained for the Haber process. [2]</p>",["Nitrogen comes from the air (1), where it makes up about 78%.","It is separated by fractional distillation of liquid air (1)."],X5_N(7)),
P("The Haber process and fertilisers",7,"<p>Plant growth is improved by the availability of essential elements, such as nitrogen, and by the soil having a suitable pH.</p><p>Nitrogen-based fertilisers are made from ammonia. Ammonia is manufactured by the Haber process.</p><ol type='a'><li>Describe the Haber process giving reaction conditions and a balanced equation. (Do not discuss reaction rate and yield.) [5]</li><li>Fertilisers contain nitrogen.<br>Name the other <b>two</b> elements essential for plant growth commonly found in fertilisers. [2]</li></ol>",["(a) Nitrogen and hydrogen react together (1): N~2~ + 3H~2~ ⇌ 2NH~3~ (1).","(a) The nitrogen is from the air and the hydrogen from natural gas (methane) and steam (1).","(a) Temperature about 450 °C (1) and pressure about 200 atmospheres (accept 150 to 300) with an iron catalyst (1).","(b) phosphorus (1) and potassium (1)."],X5_N(8)),
P("Ions in fertilisers",2,"<p>Phosphate ions are present in many fertilisers.</p><ol type='a'><li>Which <b>one</b> of the following ions is also present in many fertilisers?<br>Draw a circle around the correct answer.<br>Ba^2+^ &nbsp; Cu^2+^ &nbsp; F^−^ &nbsp; NO~3~^−^ [1]</li><li>Why do farmers put fertilisers on their fields? [1]</li></ol>",["(a) NO~3~^−^ (1): nitrate supplies nitrogen.","(b) To replace the essential elements (N, P, K) taken from the soil, so plants grow better / crop yield increases (1)."],X5_N(9)),
P("Other elements in fertilisers",2,"<p>Ions of the element potassium, K, are present in most fertilisers.</p><p>State the names of two <b>other</b> elements that are in most fertilisers.<br>1 ........<br>2 ........ [2]</p>",["nitrogen (1) and phosphorus (1), in either order."],X5_N(10)),
P("Iron as a catalyst",2,"<p>Iron is a typical transition element.</p><p>Iron:</p><ul><li>acts as a catalyst</li><li>forms coloured compounds</li><li>has more than one oxidation state.</li></ul><p>Name <b>one</b> major industrial process that uses iron as a catalyst and name the product made in this process.</p><p>process ........<br>product made ........ [2]</p>",["process: the Haber process (1).","product made: ammonia (1)."],X5_N(11)),
P("Product of the Haber process",1,"<p>A list of substances is shown.</p><p><b>ammonia &nbsp; bauxite &nbsp; carbon dioxide &nbsp; carbon monoxide &nbsp; ethanol &nbsp; hematite &nbsp; oxygen &nbsp; sodium chloride &nbsp; sulfur dioxide</b></p><p>State which substance is produced in the Haber process. [1]</p>",["ammonia (1)."],X5_N(12)),
P("The Haber process: equation, temperature and pressure",4,"<p>Iron is a typical transition element. It is the catalyst used in the Haber process.</p><ol type='a'><li>Write the equation for the reaction that occurs in the Haber process. [2]</li><li>State the temperature and pressure used in the Haber process. Include units.<br>temperature ........<br>pressure ........ [2]</li></ol>",["(a) N~2~ + 3H~2~ ⇌ 2NH~3~. Correct formulae (1), balanced (1).","(b) temperature: about 450 °C (accept 400 to 500 °C) (1).","(b) pressure: about 200 atmospheres (accept 150 to 300 atm, or 20 000 kPa) (1)."],X5_N(13)),
P("Displacing ammonia from ammonium nitrate",1,"<p>State the name of a compound that will displace ammonia from ammonium nitrate. [1]</p>",["Any alkali / base, for example sodium hydroxide or calcium hydroxide (1)."],X5_N(14)),
P("Role of iron in the Haber process",1,"<p>State the role of iron in the Haber process. [1]</p>",["It is a catalyst (1): it speeds up the reaction without being used up."],X5_N(15)),
P("Elements in fertilisers",3,"<p>Ammonia is used in the manufacture of fertilisers.</p><p>Name the <b>three</b> elements present in most fertilisers which improve plant growth.<br>1 ........<br>2 ........<br>3 ........ [3]</p>",["nitrogen (1), phosphorus (1) and potassium (1), in any order."],X5_N(16))
);

/* ---------- Carbon dioxide and methane ---------- */
const X5_C=n=>X5_S("Carbon dioxide and methane",n);
const X5_L8="<p style='text-align:center'><b>aluminium oxide &nbsp; calcium oxide &nbsp; ethanol &nbsp; nitrogen<br>iron(III) oxide &nbsp; methane &nbsp; oxygen &nbsp; silicon(IV) oxide</b></p>";
const X5_L8b="<p style='text-align:center'><b>ammonia &nbsp; bauxite &nbsp; carbon dioxide &nbsp; carbon monoxide<br>hematite &nbsp; oxygen &nbsp; sodium chloride &nbsp; sulfur dioxide</b></p>";
const X5_L9="<p style='text-align:center'><b>ammonia &nbsp; bauxite &nbsp; carbon dioxide &nbsp; carbon monoxide &nbsp; ethanol &nbsp; hematite &nbsp; oxygen &nbsp; sodium chloride &nbsp; sulfur dioxide</b></p>";
U[9].pp.push(
P("Reactant in respiration",1,"<p>The names of eight substances are given.</p>"+X5_L8+"<p>State which substance is a reactant in respiration. [1]</p>",["oxygen (1)."],X5_C(1)),
P("Product of photosynthesis (eight substances)",1,"<p>The names of eight substances are given.</p>"+X5_L8+"<p>State which substance is a product of photosynthesis. [1]</p>",["oxygen (1)."],X5_C(2)),
P("Reactant in photosynthesis",1,"<p>Answer the following question using only the substances in the list.</p>"+X5_L8b+"<p>State which substance is a reactant in photosynthesis. [1]</p>",["carbon dioxide (1)."],X5_C(3)),
P("Carbon monoxide, carbon dioxide and methane as pollutants",5,"<p>Carbon monoxide, carbon dioxide and methane are all atmospheric pollutants.</p><ul><li>Give the sources of these gases.</li><li>Describe the effects that both carbon dioxide and methane have on the environment.</li><li>State an adverse effect of carbon monoxide on health.</li></ul><p>[5]</p>",["Carbon monoxide comes from the incomplete combustion of carbon-containing fuels, for example in car engines (1).","Carbon dioxide comes from complete combustion of fuels / respiration / thermal decomposition of carbonates (1).","Methane comes from decomposition of vegetation / digestion in cattle / rice paddies / landfill sites (1).","Carbon dioxide and methane are greenhouse gases, so they increase global warming / cause climate change (1).","Carbon monoxide is toxic: it combines with haemoglobin and stops blood carrying oxygen (1)."],X5_C(4)),
P("Other sources of carbon dioxide",2,"<p>Carbon dioxide is formed:</p><ul><li>when an acid reacts with a carbonate</li><li>as a product of the complete combustion of carbon-containing substances</li></ul><p>State <b>two</b> other sources of carbon dioxide.<br>1 ........<br>2 ........ [2]</p>",["Any two (1) + (1): respiration; fermentation (of sugars); thermal decomposition of carbonates (e.g. making lime from limestone); volcanic eruptions."],X5_C(5)),
P("Plants and carbon dioxide",1,"<p>Name the process in the carbon cycle by which plants remove carbon dioxide from the atmosphere. [1]</p>",["photosynthesis (1)."],X5_C(6)),
P("Complete combustion of ethanol",2,"<p>Name the <b>two</b> products formed when ethanol undergoes complete combustion.<br>1 ........<br>2 ........ [2]</p>",["carbon dioxide (1) and water (1), in either order."],X5_C(7)),
P("Heating sodium hydrogencarbonate",1,"<p>Sodium hydrogencarbonate is found in baking powder.</p><p>When sodium hydrogencarbonate is heated it forms three products.</p><p style='text-align:center'>2NaHCO~3~ → Na~2~CO~3~ + H~2~O + CO~2~</p><p>Name the type of reaction that takes place when sodium hydrogencarbonate reacts in this way. [1]</p>",["thermal decomposition (1)."],X5_C(8)),
P("Thermal decomposition",2,"<p>Calcium oxide is made by the thermal decomposition of calcium carbonate.</p><p>State the meaning of the term <i>thermal decomposition</i>. [2]</p>",["A compound is broken down by heat (1) into two or more simpler substances (1)."],X5_C(9)),
P("Collecting carbon dioxide from calcium carbonate and acid",4,"<p>Carbon dioxide is produced when dilute hydrochloric acid reacts with powdered calcium carbonate.</p><p style='text-align:center'>CaCO~3~ + 2HCl → CaCl~2~ + CO~2~ + H~2~O</p><p>The apparatus used to investigate the volume of carbon dioxide produced has a delivery tube whose open end sits under an upturned, water-filled graduated tube (<b>M</b>) standing in a trough of water. The reaction vessel is not shown.</p><ol type='a'><li>Describe what must be added to complete the apparatus so that the gas reaches the graduated tube. [2]</li><li>Name the piece of apparatus labelled <b>M</b> in the diagram. [1]</li><li>Suggest the name of another piece of apparatus that can be used to measure the volume of carbon dioxide produced. [1]</li></ol>",["(a) A flask / conical flask containing the acid and the calcium carbonate (1), closed with a bung that is connected to the other end of the delivery tube (1).","(b) measuring cylinder (1).","(c) gas syringe (1)."],X5_C(10)),
P("Product of respiration",1,"<p>A list of substances is shown.</p>"+X5_L9+"<p>State which substance is a product of respiration. [1]</p>",["carbon dioxide (1)."],X5_C(11)),
P("Product of photosynthesis (list of substances)",1,"<p>Answer the following question using only the substances in the list.</p>"+X5_L8b+"<p>State which substance is a product of photosynthesis. [1]</p>",["oxygen (1)."],X5_C(12)),
P("Greenhouse gas",1,"<p>The names of eight substances are given.</p>"+X5_L8+"<p>State which substance is a greenhouse gas. [1]</p>",["methane (1)."],X5_C(13))
);

/* ---------- Uses of metals ---------- */
const X5_U=n=>X5_S("Uses of metals",n);
const X5_Q2U=TBL(["substance","strength","ductility (how easy it is to pull into a wire)","hardness","conductivity of heat"],[["<b>A</b>","weak","poor","hard","poor"],["<b>B</b>","strong","not ductile","very hard","good"],["<b>C</b>","very strong","very good","hard","good"],["<b>D</b>","weak","poor","soft","good"]],560);
U[8].pp.push(
P("Zinc coating and rusting",4,"<p>Iron does not rust when it is completely coated with zinc. When the zinc is scratched, the iron still does not rust.</p><ol type='a'><li>Explain why the iron does <b>not</b> rust when it is completely coated with zinc. [1]</li><li>Explain why the iron still does <b>not</b> rust when the zinc is scratched. [3]</li></ol>",["(a) The zinc coating keeps oxygen and water away from the iron (1).","(b) Zinc is more reactive than iron (1), so it reacts with oxygen and water in preference to the iron / it corrodes instead of the iron (1). This is sacrificial protection: the zinc loses electrons (is oxidised) and the iron is protected (1)."],X5_U(1)),
P("Choosing substances from their properties",6,"<p>Some properties of four substances, <b>A</b>, <b>B</b>, <b>C</b> and <b>D</b>, are shown in the table.</p>"+X5_Q2U+"<p>Answer these questions using only the information in the table.</p><ol type='a'><li>State which substance, <b>A</b>, <b>B</b>, <b>C</b> or <b>D</b>, is best used in the core of an overhead electricity cable.<br>Explain your answer.<br>substance ........<br>explanation ........ [3]</li><li>State which substance, <b>A</b>, <b>B</b>, <b>C</b> or <b>D</b>, is best used for the tip of a drill.<br>Explain your answer.<br>substance ........<br>explanation ........ [3]</li></ol>",["(a) substance C (1).","(a) It is very strong, so it can support its own weight between pylons (1), and it has very good ductility so it can be drawn into a wire (1). (It also conducts well.)","(b) substance B (1).","(b) It is very hard, so it can cut into other materials (1), and it is strong so it will not break or wear away (1)."],X5_U(2)),
P("Rusting and galvanising",3,"<p>Iron is a transition element.</p><ol type='a'><li>Which <b>two</b> substances react with iron to form rust?<br>1 ........<br>2 ........ [2]</li><li>Which metal is used to galvanise iron? [1]</li></ol>",["(a) oxygen (1) and water (1), in either order.","(b) zinc (1)."],X5_U(3)),
P("Substance used for food containers",1,"<p>The following formulae represent different substances.</p><p style='text-align:center'>Al &nbsp; Ag &nbsp; CaCO~3~ &nbsp; CH~4~ &nbsp; Cl~2~ &nbsp; Cu &nbsp; SO~2~</p><p>State which of these substances is used to make food containers. [1]</p>",["Al (1), aluminium."],X5_U(4)),
P("Electrical conductor in cables",1,"<p>The following are the symbols and formulae of some elements and compounds.</p><p style='text-align:center'>Ar &nbsp; Ca(OH)~2~ &nbsp; Cl~2~ &nbsp; CO~2~ &nbsp; Cu &nbsp; Fe &nbsp; SO~2~ &nbsp; V~2~O~5~</p><p>State which element or compound is used as an electrical conductor in cables. [1]</p>",["Cu (1), copper."],X5_U(5)),
P("Uses of mild steel and stainless steel",2,"<p>Steel is an alloy.</p><p>State <b>one</b> use of:<br>mild steel, ........<br>stainless steel. ........ [2]</p>",["mild steel (1): for example car bodies, machinery, building girders or ships.","stainless steel (1): for example cutlery, chemical plant or surgical instruments."],X5_U(6)),
P("Aluminium in food and drink containers",2,"<p>Aluminium is in Group III of the Periodic Table.</p><p>Explain why aluminium is often used in containers for food and drinks. [2]</p>",["It is resistant to corrosion because of its protective oxide layer (1).","It has a low density / is light, and is non-toxic (accept malleable, easily shaped) (1)."],X5_U(7)),
P("Copper alloys in coins",2,"<p>Alloys of copper are used to make coins.</p><ol type='a'><li>What is meant by the term <i>alloy</i>? [1]</li><li>Suggest why an alloy of copper is used to make coins instead of using pure copper. [1]</li></ol>",["(a) A mixture of a metal with one or more other elements (usually other metals) (1).","(b) The alloy is harder / stronger / more resistant to wear or corrosion than pure copper, so the coins last longer (1)."],X5_U(8)),
P("Stainless steel",2,"<p>Stainless steel is an alloy of iron.</p><ol type='a'><li>What is meant by the term <i>alloy</i>? [1]</li><li>Give <b>one</b> common use of stainless steel. [1]</li></ol>",["(a) A mixture of a metal with one or more other elements (1).","(b) Cutlery, sinks, chemical plant or surgical instruments (any one) (1)."],X5_U(9)),
P("Cobalt in steel alloys",2,"<p>Cobalt is added to iron to make steel alloys.</p><ol type='a'><li>What is meant by the term <i>alloy</i>? [1]</li><li>Give <b>one</b> reason why alloys are used instead of pure metals. [1]</li></ol>",["(a) A mixture of a metal with one or more other elements (1).","(b) Alloys are harder / stronger / more resistant to corrosion than the pure metal (any one) (1)."],X5_U(10)),
P("Alloy containing zinc",2,"<p>Zinc is an important metal. Its uses include making alloys and the construction of dry cells (batteries).</p><p>Name an alloy which contains zinc. What is the other metal in this alloy?<br>name of alloy ........<br>other metal in alloy ........ [2]</p>",["name of alloy: brass (1).","other metal in alloy: copper (1)."],X5_U(11)),
P("Alloy of zinc and copper",1,"<p>Name the alloy that contains zinc and copper only. [1]</p>",["brass (1)."],X5_U(12)),
P("Transition elements and Group I elements",5,"<p>Transition elements and Group I elements have some similar physical properties.</p><ol type='a'><li>They can both:<ul><li>be hammered into a shape</li><li>conduct electricity</li><li>be stretched into wires.</li></ul>(i) Name the term used to describe the ability of elements to be hammered into a shape. [1]<br>(ii) Describe what happens to the particles in iron when it is hammered into a shape. [1]<br>(iii) Suggest why copper, rather than other transition elements, is used for wires which conduct electricity. [1]</li><li>Transition elements are harder and stronger than Group I elements.<br>Describe how <b>two</b> other <b>physical</b> properties of transition elements are different from those of Group I elements.<br>1 ........<br>2 ........ [2]</li></ol>",["(a)(i) malleability / malleable (1).","(a)(ii) The layers of atoms / ions slide over each other (1).","(a)(iii) Copper is a very good conductor and is unreactive, so it does not corrode (1).","(b) Transition elements have higher melting points (1) and higher densities (1) than Group I elements."],X5_U(13))
);

/* ---------- Reactivity series ---------- */
