const X5_ORD=(a,b)=>"<p style='text-align:center'><b>"+a+"</b> ← ......... ← ......... ← ......... → <b>"+b+"</b></p>";
const X5_Q1R=TBL(["metal","observations"],[["zinc","no reaction with cold water"],["magnesium","gives a few bubbles with hot water, does not disappear"],["calcium","gives off bubbles steadily with cold water, gets smaller slowly"],["barium","........"]],520);
const X5_Q2R=TBL(["metal","observations"],[["calcium","reacts rapidly with cold water"],["cerium","reacts slowly with hot water and very rapidly with steam"],["cobalt","reacts with steam when cobalt powder is very hot"],["iron","reacts very slowly with hot water and readily with steam"]],520);
const X5_Q3R=TBL(["metal","observation with dilute hydrochloric acid","observation with concentrated hydrochloric acid"],[["beryllium","bubbles form rapidly","bubbles form very rapidly"],["copper","no bubbles seen","no bubbles seen"],["iron","bubbles form very slowly","bubbles form slowly"],["nickel","no bubbles seen","bubbles form slowly"]],520);
const X5_Q8R=TBL(["aqueous solution","lead Pb","magnesium Mg","zinc Zn","silver Ag"],[["lead(II) nitrate","—","✓","✓","✗"],["magnesium nitrate","........","—","........","........"],["zinc nitrate","........","........","—","........"],["silver nitrate","........","........","........","—"]],520);
const X5_Q16R=TBL(["metal oxide","conditions needed"],[["lead oxide","moderate heating to about 200 °C needed"],["iron oxide","high temperature furnace at 750 °C needed"],["magnesium oxide","temperatures above 1000 °C needed"],["zinc oxide","very high temperature furnace at 900 °C needed"]],520);
const X5_Q17R=TBL(["metal","observations"],[["copper","turns black very slowly"],["gold","no reaction"],["sodium","reacts explosively"],["tin","turns black slowly"]],460);
U[8].pp.push(
P("Reactivity of zinc, magnesium, calcium and barium",4,"<p>The order of reactivity of zinc, magnesium, calcium and barium is shown below.</p><p style='text-align:center'>zinc → magnesium → calcium → barium<br>least reactive ———→ most reactive</p><ol type='a'><li>Equal-sized pieces of zinc, magnesium, calcium and barium are placed in water. Some observations from these reactions are shown in the table.<br>Complete the box for barium.</li></ol>"+X5_Q1R+"<p>[2]</p><ol type='a' start='2'><li>Give the name of a metal in the above table which is extracted by heating with carbon. [1]</li><li>Suggest why barium cannot be extracted using carbon. [1]</li></ol>",["(a) Barium reacts very rapidly / vigorously with cold water (1), giving many bubbles of hydrogen and dissolving / disappearing quickly (1).","(b) zinc (1).","(c) Barium is more reactive than carbon, so carbon cannot displace / reduce it (1)."],X5_R(1)),
P("Order of reactivity from reactions with water and steam",2,"<p>The table below describes the reaction of water or steam with different metals.</p>"+X5_Q2R+"<p>Put these metals in order of their reactivity.</p>"+X5_ORD("least reactive","most reactive")+"<p>[2]</p>",["cobalt (least reactive), iron, cerium, calcium (most reactive).","Award (1) for calcium most reactive and cobalt least reactive, and (1) for iron then cerium in the middle."],X5_R(2)),
P("Order of reactivity from reactions with hydrochloric acid",2,"<p>The table compares the reactions of four metals with dilute and with concentrated hydrochloric acid.</p>"+X5_Q3R+"<p>Put the four metals in order of their reactivity. Put the least reactive metal first.</p>"+X5_ORD("least reactive","most reactive")+"<p>[2]</p>",["copper, nickel, iron, beryllium (least to most reactive).","Award (1) for copper first and beryllium last, and (1) for nickel then iron in the middle."],X5_R(3)),
P("Extraction of aluminium by electrolysis",5,"<p>Aluminium is extracted by electrolysis.</p><ol type='a'><li>Explain why aluminium <b>cannot</b> be extracted by reduction with carbon. [1]</li><li>Describe the role of cryolite in the extraction of aluminium by electrolysis. [1]</li><li>Name the product formed at the positive electrode. [1]</li><li>Write the ionic half-equation for the reaction at the negative electrode. [2]</li></ol>",["(a) Aluminium is more reactive than carbon, so carbon cannot displace it (1).","(b) Cryolite lowers the melting point of aluminium oxide / dissolves the aluminium oxide (1).","(c) oxygen (1).","(d) Al^3+^ + 3e^−^ → Al. Correct species (1), electrons and balance (1)."],X5_R(4)),
P("Potassium added to cold water",2,"<p>When a small piece of potassium is added to cold water, the potassium floats and disappears as it reacts.</p><p>Give <b>two</b> other observations that would be made when a small piece of potassium is added to cold water.<br>1 ........<br>2 ........ [2]</p>",["Any two (1) + (1): bubbles / fizzing; the metal melts into a ball and moves around on the surface; a lilac flame; a (lilac) spark or small explosion."],X5_R(5)),
P("Aluminium and dilute hydrochloric acid",1,"<p>When a piece of aluminium is placed in dilute hydrochloric acid, there is no immediate visible reaction.</p><p>If the aluminium is left in the dilute hydrochloric acid for several hours, bubbles start to form.</p><p>Explain why aluminium does <b>not</b> react immediately with dilute hydrochloric acid. [1]</p>",["Aluminium is covered by a layer of aluminium oxide (1) that protects the metal from the acid until it slowly dissolves."],X5_R(6)),
P("Decomposition of aluminium hydroxide",4,"<p>Aluminium hydroxide, Al(OH)~3~, decomposes when heated to form aluminium oxide and water.</p><ol type='a'><li>Write the chemical equation for this reaction. [2]</li><li>Suggest the names of <b>two</b> other aluminium compounds that decompose when heated to form aluminium oxide. [2]</li></ol>",["(a) 2Al(OH)~3~ → Al~2~O~3~ + 3H~2~O. Correct formulae (1), balanced (1).","(b) Any two (1) + (1): aluminium carbonate; aluminium nitrate."],X5_R(7)),
P("Displacement reactions of lead, magnesium, zinc and silver",3,"<p>One way of establishing a reactivity series is by displacement reactions.</p><p>A series of experiments was carried out using the metals lead, magnesium, zinc and silver. Each metal was added in turn to aqueous solutions of the metal nitrates.</p><p>The order of reactivity was found to be: magnesium (most reactive), zinc, lead, silver (least reactive).</p><p>Complete the table. ✓ = reacts, ✗ = does not react</p>"+X5_Q8R+"<p>[3]</p>",["magnesium nitrate row (1): lead ✗, zinc ✗, silver ✗.","zinc nitrate row (1): lead ✗, magnesium ✓, silver ✗.","silver nitrate row (1): lead ✓, magnesium ✓, zinc ✓.","A metal reacts only with the nitrate of a less reactive metal."],X5_R(8)),
P("Heating iron(III) oxide with zinc",3,"<p>Iron can be obtained by heating iron(III) oxide with zinc powder.</p><p style='text-align:center'>Fe~2~O~3~ + 3Zn → 2Fe + 3ZnO</p><ol type='a'><li>What can be deduced about the reactivity of zinc from this reaction? [1]</li><li>The ionic equation for this reaction is shown.<p style='text-align:center'>2Fe^3+^ + 3Zn → 2Fe + 3Zn^2+^</p>Identify the oxidising agent in this reaction. Explain your answer in terms of electron transfer.<br>oxidising agent ........<br>explanation ........ [2]</li></ol>",["(a) Zinc is more reactive than iron (1).","(b) Fe^3+^ (1) (or iron(III) oxide), because it gains electrons (1) (is reduced)."],X5_R(9)),
P("Aluminium and copper(II) sulfate",1,"<p>When a piece of aluminium metal is added to copper(II) sulfate solution the initial reaction is very slow.</p><p>Explain why the initial reaction between aluminium metal and copper(II) sulfate is very slow. [1]</p>",["The aluminium is coated with a layer of unreactive aluminium oxide (1), which has to be removed / dissolved before the metal can react."],X5_R(10)),
P("Extraction of aluminium from its ore",4,"<p>Aluminium is extracted from its ore by electrolysis.</p><ol type='a'><li>Name the main ore of aluminium. [1]</li><li>Why is aluminium <b>not</b> extracted from its ore by reduction with carbon? [1]</li><li>The main ore of aluminium contains aluminium oxide. Aluminium oxide is dissolved in molten cryolite before it is electrolysed.<br>Give <b>two</b> reasons, other than cost, why cryolite is used.<br>1 ........<br>2 ........ [2]</li></ol>",["(a) bauxite (1).","(b) Aluminium is more reactive than carbon (1).","(c) Any two (1) + (1): cryolite lowers the melting point of aluminium oxide; it dissolves the aluminium oxide so the electrolyte is a liquid; the molten mixture conducts electricity because its ions can move."],X5_R(11)),
P("Making sodium nitrate crystals from silver nitrate",10,"<p>Silver chloride can be made by reacting aqueous sodium chloride with aqueous silver nitrate. The other product of the reaction is sodium nitrate. The chemical equation for the reaction is shown.</p><p style='text-align:center'>NaCl(aq) + AgNO~3~(aq) → AgCl(s) + NaNO~3~(aq)</p><p>A student attempted to make the maximum amount of <b>sodium nitrate</b> crystals. The process involved three steps.</p><p><b>step 1</b> The student added aqueous sodium chloride to aqueous silver nitrate and stirred. Neither reagent was in excess.<br><b>step 2</b> The student filtered the mixture. The student then washed the residue and added the washings to the filtrate.<br><b>step 3</b> The student obtained sodium nitrate crystals from the filtrate.</p><ol type='a'><li>Describe what the student observed in <b>step 1</b>. [1]</li><li>Why was the residue washed in <b>step 2</b>? [1]</li><li>Give the names of the <b>two</b> processes which occurred in <b>step 3</b>. [2]</li><li>The student started with 20 cm^3^ of 0.20 mol / dm^3^ NaCl(aq).<br>Determine the amount of NaCl(aq) used. [1]</li><li>The yield of NaNO~3~ crystals was 90%.<br>Calculate the mass of NaNO~3~ crystals made. [3]</li><li>Write a chemical equation for the action of heat on sodium nitrate crystals. [2]</li></ol>",["(a) A white solid / precipitate formed (1).","(b) To remove the sodium nitrate solution that was left on the residue, so none of the product was lost (1).","(c) evaporation (1) and crystallisation (1).","(d) 20 ÷ 1000 × 0.20 = 0.0040 mol (1).","(e) 1 mol NaCl gives 1 mol NaNO~3~, so 0.0040 mol NaNO~3~ would form if the yield were 100% (1). M~r~ of NaNO~3~ = 23 + 14 + 48 = 85, so the theoretical mass is 0.0040 × 85 = 0.34 g (1). At 90%: 0.34 × 0.90 = 0.306, about 0.31 g (1).","(f) 2NaNO~3~ → 2NaNO~2~ + O~2~. Correct products (1), balanced (1)."],X5_R(12)),
P("Why aluminium is not extracted with carbon",1,"<p>Aluminium is extracted from aluminium oxide by electrolysis.</p><p>Why is aluminium <b>not</b> extracted by heating aluminium oxide with carbon? [1]</p>",["Aluminium is more reactive than carbon (so carbon cannot reduce aluminium oxide) (1)."],X5_R(13)),
P("Decomposing sodium nitrate",2,"<p>Nitrates decompose when heated.</p><p>Write a chemical equation for the decomposition of sodium nitrate when it is heated. [2]</p>",["2NaNO~3~ → 2NaNO~2~ + O~2~. Correct products (1), balanced (1)."],X5_R(14)),
P("Magnesium blocks on a ship's hull",2,"<p>The hull of a ship is made from steel (mainly iron). Metal blocks are placed on the ship's hull to prevent rusting. (The diagram shows blocks attached along the hull below the water line.)</p><p>Use your knowledge of the reactivity series to explain why:</p><ul><li>magnesium is suitable to use as the metal blocks</li><li>copper is <b>not</b> suitable to use as the metal blocks. [2]</li></ul>",["Magnesium is more reactive than iron, so it corrodes in preference to the iron (sacrificial protection) (1).","Copper is less reactive than iron, so it would not corrode in place of the iron and the iron would still rust (1)."],X5_R(15)),
P("Ease of reduction of metal oxides with carbon monoxide",2,"<p>The table describes the ease of reduction of some metal oxides with carbon monoxide.</p>"+X5_Q16R+"<p>Put these metals in order of their reactivity with carbon monoxide.</p>"+X5_ORD("least reactive","most reactive")+"<p>[2]</p>",["lead (least reactive), iron, zinc, magnesium (most reactive). The oxide that is easiest to reduce belongs to the least reactive metal.","Award (1) for lead first and magnesium last, and (1) for iron then zinc in the middle."],X5_R(16)),
P("Metals heated with liquid sulfur",2,"<p>The table shows some observations made when four metals are heated with liquid sulfur.</p>"+X5_Q17R+"<p>Use this information to put the <b>four</b> metals in order of their reactivity. Put the least reactive metal first.</p>"+X5_ORD("least reactive","most reactive")+"<p>[2]</p>",["gold (least reactive), copper, tin, sodium (most reactive).","Award (1) for gold first and sodium last, and (1) for copper then tin in the middle."],X5_R(17))
);

/* ---------- Reactivity series (continued) ---------- */
const X5_Q22D="<p><i>Diagram:</i> copper(II) nitrate is heated in a hard-glass test tube. The gases pass through a delivery tube into a second tube containing aqueous sodium hydroxide, then through another delivery tube into an upturned tube <b>X</b> filled with water standing in a trough of water (gas collected over water).</p>";
const X5_Q25D="<p><i>Diagram:</i> a zinc electrode and a copper electrode dip into dilute sulfuric acid in a beaker. A voltmeter is connected between the two electrodes by wires. The reading on the voltmeter was +1.10 V.</p>";
U[8].pp.push(
P("Rusting of iron and steel: painting and magnesium blocks",4,"<p>The metal iron and the alloy steel are commonly used materials. A problem with them is that they rust.</p><ol type='a'><li>How does painting iron and steel prevent rusting? [1]</li><li>Magnesium blocks can be attached to the bottom of steel boats.<br>Explain how the magnesium blocks prevent the whole of the bottom of the boat from rusting. [2]</li><li>Replacing the magnesium blocks with copper blocks does not prevent rusting.<br>Explain why the copper blocks do <b>not</b> prevent rusting. [1]</li></ol>",["(a) The paint forms a barrier that keeps oxygen and water away from the metal (1).","(b) Magnesium is more reactive than iron, so it loses electrons / corrodes in preference to the iron (1). The electrons flow through the whole steel hull, so all of it is protected (sacrificial protection) (1).","(c) Copper is less reactive than iron, so it does not corrode in place of the iron (1)."],X5_R(18)),
P("Magnesium and iron(III) oxide",2,"<p>A redox reaction occurs when magnesium is heated with iron(III) oxide.</p><p>Write a chemical equation for the reaction between magnesium and iron(III) oxide. [2]</p>",["3Mg + Fe~2~O~3~ → 3MgO + 2Fe. Correct formulae (1), balanced (1)."],X5_R(19)),
P("Thermal decomposition of nitrates",4,"<ol type='a'><li>Name the products formed when sodium nitrate is heated. [2]</li><li>When copper(II) nitrate, Cu(NO~3~)~2~, undergoes thermal decomposition, three products are formed. One of the products is nitrogen dioxide, NO~2~.<br>Write a chemical equation for the thermal decomposition of copper(II) nitrate. [2]</li></ol>",["(a) sodium nitrite (1) and oxygen (1).","(b) 2Cu(NO~3~)~2~ → 2CuO + 4NO~2~ + O~2~. Correct formulae (1), balanced (1)."],X5_R(20)),
P("Decomposition of copper(II) nitrate: oxygen and nitrogen dioxide",5,"<p>Copper(II) nitrate, Cu(NO~3~)~2~, decomposes when it is heated. The only solid product is copper(II) oxide, CuO. There are two gaseous products. One of the gaseous products is oxygen.</p><ol type='a'><li>Describe a test for oxygen.<br>test ........<br>result ........ [2]</li><li>Name the other gaseous product. Describe its appearance.<br>name ........<br>appearance ........ [2]</li><li>Write a chemical equation for the thermal decomposition of copper(II) nitrate. [1]</li></ol>",["(a) test: put a glowing splint into the gas (1). result: it relights (1).","(b) name: nitrogen dioxide (1). appearance: brown gas (1).","(c) 2Cu(NO~3~)~2~ → 2CuO + 4NO~2~ + O~2~ (1)."],X5_R(21)),
P("Apparatus for decomposing copper(II) nitrate",3,"<p>Copper(II) nitrate decomposes when heated. Two gases, oxygen and nitrogen dioxide, and a solid are made in the reaction.</p><p>A sample of copper(II) nitrate was decomposed using the apparatus described.</p>"+X5_Q22D+"<ol type='a'><li>Complete the chemical equation for the reaction.<br>2Cu(NO~3~)~2~ → O~2~ + ........NO~2~ + ........ [2]</li><li>Only oxygen gas is collected at <b>X</b>.<br>Explain why. [1]</li></ol>",["(a) 4 in front of NO~2~ (1) and CuO with a coefficient of 2, i.e. 2CuO (1).","(b) Nitrogen dioxide is acidic and reacts with / is absorbed by the sodium hydroxide solution (1), so only oxygen passes on to be collected."],X5_R(22)),
P("Displacement reactions of lead, nickel and silver",6,"<p>Displacement reactions occur between metals and metal ions.</p><p>Displacement reactions can be used to determine the order of reactivity of metals such as lead (Pb), nickel (Ni), and silver (Ag).</p><p>The ionic equation for a displacement reaction is shown.</p><p style='text-align:center'>Ni(s) + Pb^2+^(aq) → Pb(s) + Ni^2+^(aq)</p><p>The ionic half-equations for this reaction are shown.</p><p style='text-align:center'>Ni(s) → Ni^2+^(aq) + 2e^−^<br>Pb^2+^(aq) + 2e^−^ → Pb(s)</p><p>The ionic half-equations show that electrons are donated by nickel atoms and accepted by lead ions.</p><ol type='a'><li>(i) Identify the reducing agent in the displacement reaction. Give a reason for your answer.<br>reducing agent ........<br>reason ........ [2]<br>(ii) What is the general term given to the type of reaction in which electrons are transferred from one species to another? [1]</li><li>The ionic equation for another displacement reaction is shown.<p style='text-align:center'>Pb(s) + 2Ag^+^(aq) → 2Ag(s) + Pb^2+^(aq)</p>Write the <b>two</b> ionic half-equations for this reaction.<br>1 ........<br>2 ........ [2]</li><li>Use the information in <b>(a)</b> and <b>(b)</b> to put the three metals lead, nickel and silver in order of reactivity (most reactive at the top, least reactive at the bottom). [1]</li></ol>",["(a)(i) reducing agent: nickel / Ni (1), because it donates (loses) electrons (1).","(a)(ii) redox (1).","(b) Pb → Pb^2+^ + 2e^−^ (1) and Ag^+^ + e^−^ → Ag (1).","(c) nickel (most reactive), then lead, then silver (least reactive) (1)."],X5_R(23)),
P("Magnesium, aluminium and copper(II) sulfate",5,"<p>The positions of some common metals in the reactivity series are shown: magnesium (most reactive), aluminium, copper (least reactive).</p><ol type='a'><li>When magnesium is placed in aqueous copper(II) sulfate a displacement reaction occurs immediately.<br>Write an ionic equation for the reaction. Include state symbols. [2]</li><li>State <b>two</b> observations you would make when magnesium is placed in aqueous copper(II) sulfate.<br>1 ........<br>2 ........ [2]</li><li>When aluminium foil is added to aqueous copper(II) sulfate no immediate reaction takes place.<br>Explain why. [1]</li></ol>",["(a) Mg(s) + Cu^2+^(aq) → Mg^2+^(aq) + Cu(s). Correct species and balance (1), correct state symbols (1).","(b) Any two (1) + (1): the blue solution fades / becomes colourless; a pink-brown solid forms; the magnesium gets smaller; the mixture warms.","(c) Aluminium is covered with a layer of aluminium oxide that stops it reacting at first (1)."],X5_R(24)),
P("Electrochemical cell with zinc and copper electrodes",4,"<p>A student used the following electrochemical cell.</p><p>The reading on the voltmeter was +1.10 V.</p>"+X5_Q25D+"<ol type='a'><li>State the direction of electron flow in the external wires of the cell (from which electrode to which). [1]</li><li>Suggest the change, if any, in the voltmeter reading if the zinc electrode was replaced with an iron electrode.<br>Explain your answer. [2]</li><li>The zinc electrode was replaced with a silver electrode. The reading on the voltmeter was −0.46 V.<br>Suggest why the sign of the voltmeter reading became negative. [1]</li></ol>",["(a) From the zinc electrode through the wire / voltmeter to the copper electrode (1). (The question's diagram asked for an arrow showing this.)","(b) The voltage would be lower (1), because iron is less reactive than zinc, so the difference in reactivity between the two electrodes is smaller (1).","(c) Silver is less reactive than copper, so the electron flow is reversed: electrons now flow from copper to silver (1)."],X5_R(25)),
P("Heating sodium nitrate",2,"<p>Write the chemical equation to show the action of heat on sodium nitrate, NaNO~3~. [2]</p>",["2NaNO~3~ → 2NaNO~2~ + O~2~. Correct products (1), balanced (1)."],X5_R(26)),
P("Aluminium less reactive than expected",1,"<p>In an experiment, a sample of aluminium appeared less reactive than expected.</p><p>Explain why. [1]</p>",["The aluminium was covered by an unreactive layer of aluminium oxide (1)."],X5_R(27)),
P("Hydrochloric acid and magnesium carbonate",4,"<p>Acids have characteristic properties.</p><p>Hydrochloric acid reacts with magnesium carbonate.</p><p>Name the products of this reaction and give the observations. [4]</p>",["products: magnesium chloride (1), carbon dioxide (1) and water (1).","observation: bubbles / fizzing (effervescence) as the carbonate dissolves (1)."],X5_R(28))
);

/* ---------- Extraction of metals ---------- */
const X5_E=n=>X5_S("Extraction of metals",n);
const X5_BF="<p><i>Diagram of the blast furnace:</i> coke (carbon), limestone and iron ore are fed in at the top. Hot air is blown in near the bottom. Waste gases leave at the top. At the base there are two outlets: the <b>slag</b> outlet is <b>above</b> the <b>molten iron</b> outlet. The furnace has a firebrick lining. In the lower part of the furnace CO~2~ forms, and higher up CO forms.</p>";
U[8].pp.push(
P("Zinc compounds that react with hydrochloric acid",2,"<p>Name <b>two</b> zinc compounds which react with dilute hydrochloric acid to form zinc chloride.<br>1 ........<br>2 ........ [2]</p>",["Any two (1) + (1): zinc oxide; zinc hydroxide; zinc carbonate."],X5_E(1)),
P("Making zinc chloride crystals",9,"<p>A student wanted to make some zinc chloride crystals.</p><p>The student followed the procedure shown.</p><p><b>step 1</b> Add excess zinc powder to dilute hydrochloric acid to form aqueous zinc chloride.<br><b>step 2</b> Remove unreacted zinc powder from the aqueous zinc chloride.<br><b>step 3</b> Heat the solution until it is saturated.<br><b>step 4</b> Allow the saturated solution to cool and remove the crystals that form.</p><ol type='a'><li>Write the equation for the reaction in <b>step 1</b>. Include state symbols. [3]</li><li>Explain why <b>excess</b> zinc powder is added to <b>step 1</b>. [1]</li><li>Suggest how unreacted zinc powder is removed in <b>step 2</b>. [1]</li><li>A saturated solution is formed in <b>step 3</b>.<br>Suggest what is meant by the term <i>saturated solution</i>. [2]</li><li>Explain why crystals form as the solution cools in <b>step 4</b>. [1]</li><li>If excess calcium metal is used instead of excess zinc powder in <b>step 1</b>, pure calcium chloride crystals do <b>not</b> form.<br>Explain why. [1]</li></ol>",["(a) Zn(s) + 2HCl(aq) → ZnCl~2~(aq) + H~2~(g). Correct formulae (1), balanced (1), correct state symbols (1).","(b) To make sure all the hydrochloric acid is used up / reacted (1).","(c) filtration (1).","(d) A solution that contains the maximum amount of dissolved solute (1) at a particular temperature (1).","(e) The solubility of zinc chloride decreases as the temperature falls, so the extra solute comes out of solution as crystals (1).","(f) Calcium is so reactive that it also reacts with the water in the solution, forming calcium hydroxide, so the calcium chloride would be impure (1)."],X5_E(2)),
P("The blast furnace: ore, slag and hot air",6,"<p>Iron is extracted by heating a mixture of coke (carbon), limestone and iron ore in air in a blast furnace.</p>"+X5_BF+"<ol type='a'><li>Name the ore of iron added to the blast furnace. [1]</li><li>The impurities in the iron ore are removed as slag.<br>(i) What information in the diagram shows that slag is less dense than molten iron? [1]<br>(ii) Which <b>one</b> of the substances added to the blast furnace helps to remove the impurities?<br>Explain how it does this.<br>substance ........<br>explanation ........ [3]</li><li>Hot air is blown into the blast furnace.<br>Explain why. [1]</li></ol>",["(a) hematite (1).","(b)(i) The slag outlet is above the molten iron outlet, so the slag floats on top of the iron (1).","(b)(ii) substance: limestone (1). It decomposes on heating to form calcium oxide (1), which reacts with the acidic impurities (silicon dioxide) to form slag (1).","(c) It supplies the oxygen needed for the coke to burn / to produce heat (1)."],X5_E(3)),
P("Ore of aluminium",1,"<p>Name the ore of aluminium which mainly consists of aluminium oxide. [1]</p>",["bauxite (1)."],X5_E(4)),
P("Reactions in the blast furnace: completing sentences",4,"<p>Iron is extracted from iron ore using a blast furnace. The solid substances added to the blast furnace are iron ore, coke and limestone (calcium carbonate).</p><p>Complete the sentences about the reactions which occur in a blast furnace using words from the list.</p><p style='text-align:center'><b>air &nbsp; decomposes &nbsp; dioxide &nbsp; monoxide<br>nitrogen &nbsp; oxidises &nbsp; slag &nbsp; tetrachloride</b></p><p>The coke burns in a blast of hot ........ to form carbon dioxide. This reacts with further hot coke to form carbon ........ . This gas reduces the iron(III) oxide in the iron ore to iron.</p><p>The limestone ........ to form lime (calcium oxide) which reacts with impurities in the iron to form ........ . [4]</p>",["air (1).","monoxide (1).","decomposes (1).","slag (1)."],X5_E(5)),
P("Hydrated zinc sulfate from zinc and sulfuric acid",3,"<p>Zinc reacts with dilute sulfuric acid to produce aqueous zinc sulfate.</p><p style='text-align:center'>Zn(s) + H~2~SO~4~(aq) → ZnSO~4~(aq) + H~2~(g)</p><p>Hydrated zinc sulfate crystals are made from aqueous zinc sulfate.</p><p><b>Step 1</b> Solid zinc is added to dilute sulfuric acid until zinc is in excess.<br><b>Step 2</b> Excess zinc is separated from aqueous zinc sulfate by filtration.<br><b>Step 3</b> Aqueous zinc sulfate is heated until the solution is saturated.<br><b>Step 4</b> The saturated solution is allowed to cool and crystallise.<br><b>Step 5</b> The crystals are removed and dried.</p><ol type='a'><li>Name the residue in <b>step 2</b>. [1]</li><li>In <b>step 3</b>, a saturated solution is produced.<br>Describe what a saturated solution is. [2]</li></ol>",["(a) zinc (1).","(b) A solution that contains the maximum amount of dissolved solute (1) at that temperature (1)."],X5_E(6)),
P("Compounds that react with sulfuric acid to make zinc sulfate",2,"<p>Name <b>two</b> compounds each of which react with dilute sulfuric acid to produce aqueous zinc sulfate.<br>1 ........<br>2 ........ [2]</p>",["Any two (1) + (1): zinc oxide; zinc hydroxide; zinc carbonate."],X5_E(7)),
P("Extraction of aluminium: ore, carbon and cryolite",4,"<p>Aluminium is extracted from its ore by electrolysis.</p><ol type='a'><li>Name the main ore of aluminium. [1]</li><li>Why is aluminium <b>not</b> extracted from its ore by reduction with carbon? [1]</li><li>The main ore of aluminium contains aluminium oxide. Aluminium oxide is dissolved in molten cryolite before it is electrolysed.<br>Give <b>two</b> reasons, other than cost, why cryolite is used.<br>1 ........<br>2 ........ [2]</li></ol>",["(a) bauxite (1).","(b) Aluminium is more reactive than carbon (1).","(c) Any two (1) + (1): cryolite lowers the melting point of aluminium oxide; it dissolves the aluminium oxide so the electrolyte is a liquid; the molten mixture conducts electricity because its ions can move."],X5_E(8)),
P("Carbon monoxide in the blast furnace",4,"<p>Iron is extracted from the ore hematite in the blast furnace.</p><p><i>Diagram:</i> raw materials (coke, C; iron ore, Fe~2~O~3~; limestone, CaCO~3~) enter at the top; hot air enters near the bottom; waste gases leave at the top. In the lower part of the furnace CO~2~ forms and higher up CO forms. Slag and molten iron collect at the bottom.</p><p>The coke reacts with the oxygen in the air to form carbon dioxide.</p><p style='text-align:center'>C + O~2~ → CO~2~</p><ol type='a'><li>Explain why carbon monoxide is formed higher in the blast furnace. [2]</li><li>Write an equation for the reduction of hematite, Fe~2~O~3~, by carbon monoxide. [2]</li></ol>",["(a) The carbon dioxide rises and reacts with more hot coke (1): CO~2~ + C → 2CO (1), because the oxygen from the air has already been used up lower down.","(b) Fe~2~O~3~ + 3CO → 2Fe + 3CO~2~. Correct formulae (1), balanced (1)."],X5_E(9)),
P("Limestone, slag and molten iron in the blast furnace",6,"<p>Iron is extracted from the ore hematite in the blast furnace (raw materials: coke, iron ore and limestone; hot air blown in near the bottom).</p><ol type='a'><li>Limestone decomposes to form two products, one of which is calcium oxide.<br>Name the other product. [1]</li><li>Calcium oxide reacts with silicon(IV) oxide, an acidic impurity in the iron ore, to form slag.<br>Write an equation for this reaction. [2]</li><li>Explain why the molten iron and the molten slag form two layers and why molten iron is the lower layer. [2]</li><li>Suggest why the molten iron does <b>not</b> react with the air. [1]</li></ol>",["(a) carbon dioxide (1).","(b) CaO + SiO~2~ → CaSiO~3~. Correct formulae (1), balanced (1).","(c) They do not mix / are immiscible (1), and molten iron is denser than the slag (1).","(d) The layer of slag floats on top of the molten iron and keeps the air away from it (1)."],X5_E(10)),
P("Zinc blende: roasting and sulfur dioxide",3,"<p>The main ore of zinc is zinc blende, ZnS.</p><ol type='a'><li>The ore is heated in the presence of air to form zinc oxide and sulfur dioxide.<br>Write the equation for this reaction. [2]</li><li>Give a major use of sulfur dioxide. [1]</li></ol>",["(a) 2ZnS + 3O~2~ → 2ZnO + 2SO~2~. Correct formulae (1), balanced (1).","(b) Making sulfuric acid, or bleaching, or a food preservative (any one) (1)."],X5_E(11)),
P("Extraction of zinc from zinc blende",5,"<p>Zinc is obtained from the ore, zinc blende, ZnS.</p><p>Describe the extraction of zinc from its ore, zinc blende. Include at least one balanced equation in your description. [5]</p>",["The zinc blende is roasted (heated strongly) in air (1) to form zinc oxide and sulfur dioxide: 2ZnS + 3O~2~ → 2ZnO + 2SO~2~ (1).","The zinc oxide is heated with carbon (coke) (1): ZnO + C → Zn + CO (1).","Zinc is less reactive than carbon, so carbon can reduce the zinc oxide (1)."],X5_E(12)),
P("Elements in part of the Periodic Table",5,"<p>The diagram shows part of the Periodic Table. It contains the elements H; K; Mg and Ca; Al; Cr, Fe, Cu and Zn; N, O, F and Ne; and Cl, Br and I.</p><p>Answer the following questions using only the symbols of the elements in the diagram. Each symbol may be used once, more than once or not at all.</p><p>State the symbol of the element that:</p><ol type='a'><li>is a monoatomic gas at room temperature [1]</li><li>is a liquid at room temperature [1]</li><li>forms a stable ion of type X^2−^ [1]</li><li>is extracted from hematite [1]</li><li>forms an ion whose aqueous solution gives a grey-green precipitate on addition of aqueous ammonia. [1]</li></ol>",["(a) Ne (1).","(b) Br (1).","(c) O (1).","(d) Fe (1).","(e) Cr (1): chromium(III) hydroxide is grey-green."],X5_E(13)),
P("Reactions in the blast furnace: description",5,"<p>A series of reactions occurs in a blast furnace during the extraction of iron from hematite.</p><p>Describe these reactions.</p><p>Include:</p><ul><li><b>one</b> chemical equation for the reduction of hematite</li><li><b>one</b> chemical equation for the formation of slag. [5]</li></ul>",["Coke burns in the hot air to form carbon dioxide (1).","The carbon dioxide reacts with more coke to form carbon monoxide (1).","Carbon monoxide reduces hematite to iron (1): Fe~2~O~3~ + 3CO → 2Fe + 3CO~2~.","Limestone decomposes to calcium oxide and carbon dioxide (1).","Calcium oxide reacts with silicon dioxide to form slag (1): CaO + SiO~2~ → CaSiO~3~."],X5_E(14)),
P("Calcium carbonate in the extraction of iron",3,"<p>Complete the sentences about the use of calcium carbonate in the extraction of iron using words from the list.</p><p style='text-align:center'><b>bauxite &nbsp; dioxide &nbsp; hematite &nbsp; monoxide &nbsp; silicon &nbsp; slag</b></p><p>The main ore of iron is called ........ . The main impurity in the iron ore is silicon(IV) oxide.</p><p>Calcium carbonate added to the blast furnace decomposes to form calcium oxide and carbon ........ . The calcium oxide reacts with the silicon(IV) oxide to form ........ . [3]</p>",["hematite (1).","dioxide (1).","slag (1)."],X5_E(15))
);

/* ---------- Extraction of metals (continued) ---------- */
const X5_BF2="<p><i>Diagram:</i> waste gases leave at the top; the raw materials (coke, iron ore, limestone) enter at the top; air enters near the bottom; slag and molten iron leave through two outlets at the base.</p>";
const X5_BF3="<p><i>Diagram:</i> waste gases leave at the top; the raw materials (coke, iron ore, limestone) enter at the top. Near the bottom there are three pipes: <b>A</b> is at the level of the blast of air entering the furnace (the pipe opposite the air inlet), <b>B</b> is a lower outlet, and below it is the outlet labelled molten iron.</p>";
const X5_LIST9="<p style='text-align:center'><b>ammonia &nbsp; bauxite &nbsp; carbon dioxide &nbsp; carbon monoxide &nbsp; ethanol &nbsp; hematite &nbsp; oxygen &nbsp; sodium chloride &nbsp; sulfur dioxide</b></p>";
const X5_LIST8="<p style='text-align:center'><b>ammonia &nbsp; bauxite &nbsp; carbon dioxide &nbsp; carbon monoxide &nbsp; hematite &nbsp; oxygen &nbsp; sodium chloride &nbsp; sulfur dioxide</b></p>";
U[8].pp.push(
P("Substance added to a blast furnace to remove impurities",1,"<p>The following formulae represent different substances.</p><p style='text-align:center'>Al &nbsp; Ag &nbsp; CaCO~3~ &nbsp; CH~4~ &nbsp; Cl~2~ &nbsp; Cu &nbsp; SO~2~</p><p>State which of these substances is added to a blast furnace to remove impurities during the production of iron. [1]</p>",["CaCO~3~ (1), calcium carbonate (limestone)."],X5_E(16)),
P("Iron from its ore using coke in a blast furnace",7,"<p>Iron is extracted from its ore using coke in a blast furnace.</p>"+X5_BF2+"<ol type='a'><li>Name the ore of iron which is mainly iron(III) oxide. [1]</li><li>Describe the reactions occurring in the blast furnace.<br>In your answer, include:<ul><li><b>two</b> reasons for using coke in the blast furnace</li><li>a chemical equation for the reduction of iron(III) oxide</li><li>an explanation for using limestone in the blast furnace. [6]</li></ul></li></ol>",["(a) hematite (1).","(b) Coke burns in the hot air, releasing the heat needed to run the furnace (1).","(b) Coke is also the source of the carbon monoxide that does the reduction (carbon dioxide reacts with more coke to form carbon monoxide) (1).","(b) Fe~2~O~3~ + 3CO → 2Fe + 3CO~2~. Correct formulae (1), balanced (1).","(b) Limestone decomposes to calcium oxide (1), which reacts with the acidic impurity silicon dioxide to form slag, which can be removed (1) (CaO + SiO~2~ → CaSiO~3~)."],X5_E(17)),
P("Another raw material of the blast furnace",1,"<p>Three of the raw materials added to a blast furnace used to extract iron from hematite are coke, hematite and limestone.</p><p>Name <b>one</b> other raw material added to the blast furnace. [1]</p>",["Air (hot air / oxygen) (1)."],X5_E(18)),
P("Aluminium oxide and carbon",1,"<p>Aluminium is extracted from aluminium oxide by electrolysis.</p><p>Why is aluminium <b>not</b> extracted by heating aluminium oxide with carbon? [1]</p>",["Aluminium is more reactive than carbon, so carbon cannot reduce aluminium oxide (1)."],X5_E(19)),
P("Electrolysis of aluminium oxide and cryolite",8,"<p>Aluminium can be extracted by electrolysis using the apparatus described.</p><p><i>Diagram:</i> a steel tank lined with carbon contains molten aluminium oxide and cryolite, with molten aluminium collecting at the bottom. Two carbon anodes (positive, connected to the positive terminal of the power supply) dip into the mixture from above. The lined tank is the cathode (connected to the negative terminal).</p><ol type='a'><li>Name the type of particle responsible for the transfer of charge in<br>the wires, ........<br>the electrolyte. ........ [2]</li><li>Give <b>two</b> reasons why cryolite is used.<br>1 ........<br>2 ........ [2]</li><li>Write the ionic half-equation for the formation of aluminium during the electrolysis. [1]</li><li>Explain how carbon dioxide gas is formed at the anodes. [3]</li></ol>",["(a) wires: electrons (1). electrolyte: ions (1).","(b) Any two (1) + (1): it lowers the melting point of aluminium oxide; it dissolves the aluminium oxide; it saves energy / cost.","(c) Al^3+^ + 3e^−^ → Al (1).","(d) Oxide ions are attracted to the anodes and lose electrons to form oxygen: 2O^2−^ → O~2~ + 4e^−^ (1). The anodes are made of carbon (1), which reacts with the hot oxygen to form carbon dioxide: C + O~2~ → CO~2~ (1)."],X5_E(20)),
P("Tin from cassiterite and stannite",3,"<p>Tin is a metallic element in Group IV. Its main ore is cassiterite which is an impure form of tin(IV) oxide, SnO~2~.<br>Tin also occurs in stannite, Cu~2~FeSnS~4~.</p><ol type='a'><li>Calculate the relative formula mass, <i>M</i>~r~, of Cu~2~FeSnS~4~. [1]</li><li>The <i>M</i>~r~ of SnO~2~ is 151.<br>Calculate the percentage of tin by mass in SnO~2~. [1]</li><li>The percentage of tin by mass in Cu~2~FeSnS~4~ is 27.6%.<br>Use this information and your answer to <b>(b)</b> to suggest whether it would be better to extract tin from SnO~2~ or Cu~2~FeSnS~4~.<br>Explain your answer. [1]</li></ol>",["(a) 2 × 64 + 56 + 119 + 4 × 32 = 128 + 56 + 119 + 128 = 431 (1).","(b) 119 ÷ 151 × 100 = 78.8% (1).","(c) SnO~2~ (1), because it contains a higher percentage of tin (78.8% compared with 27.6%), so more tin is obtained from the same mass of ore."],X5_E(21)),
P("Zinc blende and the zinc furnace",6,"<p>Zinc is manufactured from zinc blende. Zinc blende is an ore which consists mainly of zinc sulfide, ZnS.</p><ol type='a'><li>Zinc blende is roasted in air. One of the products is zinc oxide.<br>Name the <b>other</b> product formed in this reaction. [1]</li><li>Zinc oxide is then converted into zinc.<br>Zinc oxide and coke, a source of carbon, are heated in a furnace. Hot air is blown into the furnace.<br>(i) Give <b>two</b> reasons why coke is needed.<br>1 ........<br>2 ........ [2]<br>(ii) Write a chemical equation for the formation of zinc in the furnace. [1]<br>(iii) Zinc has a melting point of 420 °C and a boiling point of 907 °C. The temperature inside the furnace is 1200 °C.<br>Explain how this information shows that the zinc produced inside the furnace is a gas. [1]<br>(iv) The gaseous zinc is converted to molten zinc.<br>Name this change of state. [1]</li></ol>",["(a) sulfur dioxide (1).","(b)(i) Coke burns to give the heat needed (1), and it is the source of carbon / carbon monoxide that reduces the zinc oxide (1).","(b)(ii) ZnO + C → Zn + CO (1) (accept ZnO + CO → Zn + CO~2~).","(b)(iii) The furnace temperature (1200 °C) is above the boiling point of zinc (907 °C) (1).","(b)(iv) condensation (1)."],X5_E(22)),
P("Period 3 element extracted from bauxite",1,"<p>This question is about the elements in Period 3 of the Periodic Table.</p><p style='text-align:center'>Na &nbsp; Mg &nbsp; Al &nbsp; Si &nbsp; P &nbsp; S &nbsp; Cl &nbsp; Ar</p><p>State which Period 3 element is extracted from the ore bauxite. [1]</p>",["Al (1), aluminium."],X5_E(23)),
P("Ore of iron",1,"<p>Answer the following question using only the substances in the list.</p>"+X5_LIST8+"<p>State which substance is an ore of iron. [1]</p>",["hematite (1)."],X5_E(24)),
P("Main ores of zinc and aluminium",2,"<p>Name the main ores of:<br>zinc ........<br>aluminium ........ [2]</p>",["zinc: zinc blende (1).","aluminium: bauxite (1)."],X5_E(25)),
P("Ore of aluminium (list of substances)",1,"<p>A list of substances is shown.</p>"+X5_LIST9+"<p>State which substance is an ore of aluminium. [1]</p>",["bauxite (1)."],X5_E(26)),
P("Blast furnace: ore, air, slag and coke",5,"<p>This question is about iron.</p><p>Iron is extracted from its main ore in a blast furnace.</p>"+X5_BF3+"<ol type='a'><li>Name the main ore of iron used in the blast furnace. [1]</li><li>Name the substance that enters the blast furnace at <b>A</b>. [1]</li><li>Name the substance that leaves the blast furnace at <b>B</b>. [1]</li><li>Give <b>two</b> reasons for using coke in the blast furnace.<br>1 ........<br>2 ........ [2]</li></ol>",["(a) hematite (1).","(b) hot air (accept air or oxygen) (1).","(c) slag (1).","(d) Coke burns to release heat (1), and it provides carbon / carbon monoxide to reduce the iron ore (1)."],X5_E(27)),
P("Waste gases from the blast furnace",2,"<p>This question is about metals.</p><p>Iron is extracted from its main ore in a blast furnace.</p><p><i>Diagram:</i> hot air enters near the bottom; slag and molten iron (<b>A</b>) leave at the base; waste gases leave at the top.</p><p>Name <b>two</b> waste gases that leave the blast furnace.<br>1 ........<br>2 ........ [2]</p>",["Any two (1) + (1): carbon dioxide; carbon monoxide; nitrogen."],X5_E(28)),
P("Elements: fuel, oxide structures and oxidation states",6,"<p>This question is about elements.</p><p style='text-align:center'><b>aluminium &nbsp; carbon &nbsp; iron &nbsp; hydrogen &nbsp; oxygen &nbsp; silicon &nbsp; sodium &nbsp; sulfur</b></p><p>Answer the following questions about these elements. Each element may be used once, more than once or not at all.</p><ol type='a'><li>Name the element that can be used as a fuel. [1]</li><li>Name the element that forms an oxide with a similar structure to diamond. [1]</li><li>Name the element that forms an amphoteric oxide. [1]</li><li>Name the element that has oxidation states of +2 and +3. [1]</li><li>Name the element extracted from bauxite. [1]</li><li>Name the element that has atoms with the electronic structure 2,6. [1]</li></ol>",["(a) carbon or hydrogen (either) (1).","(b) silicon (1): silicon dioxide has a giant covalent structure.","(c) aluminium (1).","(d) iron (1).","(e) aluminium (1).","(f) oxygen (1)."],X5_E(29)),
P("Extracting lead from PbCO3 or PbS",1,"<p>The percentage of lead by mass in PbCO~3~ is 77.5%.</p><p>The percentage by mass of lead in PbS is 86.6%.</p><p>Suggest whether it would be better to extract lead from PbCO~3~ or PbS.</p><p>Give a reason for your answer. [1]</p>",["PbS (1), because it has the higher percentage of lead, so more lead is obtained from the same mass of ore."],X5_E(30))
);

U[8].pp.push(
P("Elements in the reactivity series",8,"<p>Some elements are shown in the order they appear in the reactivity series.</p><p>The most reactive element is at the top.</p><p style='text-align:center'><b>sodium<br>calcium<br>magnesium<br>aluminium<br>zinc<br>iron<br>hydrogen<br>copper</b></p><p>Answer the questions using the list of elements. Each element may be used once, more than once or not at all.</p><p>Identify:</p><ol type='a'><li>a non-metal [1]</li><li>a metal which is stored under oil [1]</li><li>the main component of steel [1]</li><li>a metal with three electrons in the outer shell of its atoms [1]</li><li>a metal found in brass [1]</li><li>a metal that forms chlorides of the type XCl~2~ and XCl~3~ [1]</li><li>Name <b>two</b> metals from the list which are extracted by reduction of their ores using carbon.<br>1 ........<br>2 ........ [2]</li></ol>",["(a) hydrogen (1).","(b) sodium (1).","(c) iron (1).","(d) aluminium (1).","(e) zinc (or copper) (1).","(f) iron (1): FeCl~2~ and FeCl~3~.","(g) Any two (1) + (1) from zinc, iron (copper is also accepted): these are below carbon in the reactivity series."],X5_E(31))
);

const X5_A=n=>X5_S("Air and rust",n);
const X5_L19=["ammonia","bauxite","carbon dioxide","carbon monoxide","ethanol","hematite","oxygen","sodium chloride","sulfur dioxide"];
const X5_P19="<p style='text-align:center'><b>"+X5_L19.join("<br>")+"</b></p>";
U[8].pp.push(
P("Rusting of iron",1,"<p>Iron rusts when it reacts with two substances. Name the two substances. [1]</p>",["oxygen and water (1)."],X5_A(1)),
P("Rust and phosphoric acid",3,"<p>Rust is mainly hydrated iron(III) oxide. Phosphoric acid, H~3~PO~4~, can be used to treat rust.</p><ol type='a'><li>Write a chemical equation for the reaction between iron(III) oxide and phosphoric acid to form iron(III) phosphate and water. [2]</li><li>Iron(III) phosphate is insoluble. Suggest how this helps to prevent further rusting. [1]</li></ol>",["(a) Fe~2~O~3~ + 2H~3~PO~4~ → 2FePO~4~ + 3H~2~O: correct formulae (1), correct balancing (1).","(b) An insoluble layer of iron(III) phosphate coats the surface and keeps oxygen and water away from the iron (1)."],X5_A(9)),
P("Rusting of iron and steel: painting and magnesium blocks",4,"<p>The metal iron and the alloy steel are commonly used materials. A problem with them is that they rust.</p><ol type='a'><li>How does painting iron and steel prevent rusting? [1]</li><li>Magnesium blocks can be attached to the bottom of steel boats.<br>Explain how the magnesium blocks prevent the whole of the bottom of the boat from rusting. [2]</li><li>Replacing the magnesium blocks with copper blocks does not prevent rusting.<br>Explain why the copper blocks do <b>not</b> prevent rusting. [1]</li></ol>",["(a) The paint forms a barrier that keeps oxygen and water away from the metal (1).","(b) Magnesium is more reactive than iron, so it loses electrons / corrodes in preference to the iron (1). The electrons flow through the whole steel hull, so all of it is protected (sacrificial protection) (1).","(c) Copper is less reactive than iron, so it does not corrode in place of the iron (1)."],X5_A(12)),
P("Zinc coating and rusting",4,"<p>Iron does not rust when it is completely coated with zinc. When the zinc is scratched, the iron still does not rust.</p><ol type='a'><li>Explain why the iron does <b>not</b> rust when it is completely coated with zinc. [1]</li><li>Explain why the iron still does <b>not</b> rust when the zinc is scratched. [3]</li></ol>",["(a) The zinc coating keeps oxygen and water away from the iron (1).","(b) Zinc is more reactive than iron (1), so it reacts with oxygen and water in preference to the iron / it corrodes instead of the iron (1). This is sacrificial protection: the zinc loses electrons (is oxidised) and the iron is protected (1)."],X5_A(13)),
P("Extraction of titanium",2,"<p>Titanium is extracted from an ore called rutile. Rutile is an impure form of titanium(IV) oxide, TiO~2~.</p><p>Rutile is mixed with coke and heated in a furnace through which chlorine gas is passed. The product is gaseous titanium(IV) chloride, TiCl~4~.</p><p style='text-align:center'>TiO~2~(s) + 2C(s) + 2Cl~2~(g) → TiCl~4~(g) + 2CO(g)</p><p>The gaseous titanium(IV) chloride produced is condensed into the liquid state. The titanium(IV) chloride is then separated from liquid impurities.</p><ol type='a'><li>Suggest the name of the process by which liquid titanium(IV) chloride could be separated from the liquid impurities. [1]</li><li>Carbon monoxide, CO(g), is also produced in the reaction. Why should carbon monoxide <b>not</b> be released into the atmosphere? [1]</li></ol>",["(a) fractional distillation (or distillation) (1).","(b) It is toxic / poisonous (1)."],X5_A(18)),
P("Magnesium blocks on a steel boat",3,"<p>Steel consists mainly of iron. Iron forms rust when it reacts with water and oxygen.</p><p>Magnesium blocks can be attached to the bottom of steel boats. The magnesium does not completely cover the steel.</p><p><i>Diagram: the hull of a steel boat sits in water containing dissolved oxygen; several small magnesium blocks are attached at intervals along the bottom of the hull.</i></p><ol type='a'><li>Explain how the magnesium blocks prevent iron from rusting. [2]</li><li>Explain why replacing the magnesium blocks with copper blocks will <b>not</b> prevent the bottom of the boat from rusting. [1]</li></ol>",["(a) Magnesium is more reactive than iron (1), so it corrodes / loses electrons in preference to the iron (sacrificial protection) (1).","(b) Copper is less reactive than iron, so the iron corrodes instead (1)."],X5_A(21)),
P("Sacrificial protection",3,"<p>Iron rusts when it is in contact with oxygen and water.</p><ol type='a'><li>Explain how sacrificial protection prevents rusting. [2]</li><li>State one <b>other</b> method of rust prevention. [1]</li></ol>",["(a) A more reactive metal (such as zinc or magnesium) is attached to the iron (1). The more reactive metal corrodes in preference to the iron, so the iron does not rust (1).","(b) painting / oiling / greasing / plastic coating / galvanising / plating with tin or chromium (any one) (1)."],X5_A(27))
);
U[9].pp.push(
P("Formation of nitrogen dioxide",2,"<p>Describe how nitrogen dioxide, NO~2~, forms in car engines. [2]</p>",["Nitrogen and oxygen from the air react (1) at the high temperature inside the engine (1)."],X5_A(2)),
P("Gas contributing to climate change",1,"<p>Formulae of some substances are shown: Al, Ag, CaCO~3~, CH~4~, Cl~2~, Cu, SO~2~.</p><p>Give the formula of the gas that contributes to climate change. [1]</p>",["CH~4~ (1)."],X5_A(3)),
P("Incomplete combustion of hydrocarbons",1,"<p>The names of nine gases are given: ammonia, carbon monoxide, chlorine, ethane, ethene, helium, hydrogen, neon, oxygen.</p><p>Name the gas that is formed by the incomplete combustion of hydrocarbons. [1]</p>",["carbon monoxide (1)."],X5_A(4)),
P("Separating gases from liquid air",3,"<p>Oxygen and nitrogen are separated from liquid air.</p><ol type='a'><li>Name the process used to separate oxygen and nitrogen from liquid air. [2]</li><li>State the property of oxygen and nitrogen that allows them to be separated by this process. [1]</li></ol>",["(a) fractional (1) distillation (1).","(b) They have different boiling points (1)."],X5_A(5)),
P("Acid rain from fossil fuels",2,"<p>Some fossil fuels contain sulfur. Explain how burning these fuels leads to acid rain. [2]</p>",["Burning forms sulfur dioxide (1), which dissolves in rain water to form an acid (1)."],X5_A(6)),
P("Carbon dioxide in the atmosphere",3,"<p>The concentration of carbon dioxide in the atmosphere, in parts per million (ppm), has been measured from 1960 to 2018.</p><p><i>Graph description: the concentration rises steadily from about 315 ppm in 1960 to about 408 ppm in 2018, and the rate of increase becomes greater in later years.</i></p><p>Explain why this change is of global concern. [3]</p>",["Carbon dioxide is a greenhouse gas (1) that traps heat / absorbs infrared radiation (1), so increasing concentration leads to global warming / climate change (1)."],X5_A(7)),
P("Gas that causes acid rain",1,"<p>The names of eight gases are given: ammonia, argon, carbon dioxide, helium, hydrogen, methane, neon, sulfur dioxide.</p><p>Name the gas that contributes to acid rain. [1]</p>",["sulfur dioxide (1)."],X5_A(8)),
P("Pollutants from vehicles",7,"<p>Vehicles produce the pollutants carbon monoxide, CO, nitrogen monoxide, NO, nitrogen dioxide, NO~2~, and unburnt hydrocarbons.</p><ol type='a'><li>Explain how oxides of nitrogen are formed in a vehicle engine. [2]</li><li>Describe how a catalytic converter reduces the emission of these pollutants. [4]</li><li>Lead compounds were once added to petrol. Why are lead compounds harmful? [1]</li></ol>",["(a) Nitrogen and oxygen from the air react (1) at high temperature in the engine (1).","(b) CO and NO react on the surface of the hot catalyst (1) to form carbon dioxide (1) and nitrogen (1). Unburnt hydrocarbons are oxidised to carbon dioxide and water (1).","(c) Lead compounds are toxic / poisonous (1)."],X5_A(10)),
P("Air: mixtures and separation",6,"<p>Clean, dry air is a mixture.</p><ol type='a'><li>What is meant by the term <i>mixture</i>? [1]</li><li>State the percentage of oxygen in clean, dry air, to the nearest whole number. [1]</li><li>Nitrogen and oxygen are separated from clean, dry air in an industrial process. Describe the steps of this process, using scientific terms. [3]</li><li>State the physical property of nitrogen and oxygen that allows them to be separated. [1]</li></ol>",["(a) Two or more substances that are not chemically combined (1).","(b) 21 (%) (1).","(c) The air is cooled / compressed until it becomes a liquid (1). The liquid air is fractionally distilled / warmed in a fractionating column (1). Nitrogen, with the lower boiling point, boils off first / at the top, and oxygen is collected later (1).","(d) boiling point (1)."],X5_A(14)),
P("Elements of Period 2",6,"<p>The symbols of the elements in Period 2 are Li, Be, B, C, N, O, F and Ne.</p><p>Answer the questions using these symbols. Each symbol may be used once, more than once or not at all.</p><p>Give the symbol of the element that:</p><ol type='a'><li>combines with hydrogen to make ammonia [1]</li><li>makes up about 21% of clean, dry air [1]</li><li>has atoms with only two electrons in the outer shell [1]</li><li>has atoms with only seven protons [1]</li><li>is a monoatomic gas [1]</li><li>is a soft metal that is stored in oil [1]</li></ol>",["(a) N (1).","(b) O (1).","(c) Be (1).","(d) N (1).","(e) Ne (1).","(f) Li (1)."],X5_A(15)),
P("Clean air and polluted air",11,"<p>Clean, dry air contains the gases argon, carbon dioxide, nitrogen and oxygen. Polluted air can also contain carbon monoxide, nitrogen monoxide, nitrogen dioxide and sulfur dioxide.</p><ol type='a'><li>State the percentage of nitrogen in clean, dry air, to the nearest whole number. [1]</li><li>Name the process used to separate oxygen from air. [2]</li><li>State one major adverse effect of sulfur dioxide. [1]</li><li>Describe how oxides of nitrogen are formed in a car engine. [2]</li><li>Many cars have catalytic converters in their exhaust systems. In a catalytic converter, most of the CO and NO formed in a car engine is changed into less harmful products.<br>Identify these products and state the metal catalyst used.<br>products ........<br>catalyst ........ [3]</li><li>CO is formed from the incomplete combustion of fossil fuels such as methane.<br>Write a chemical equation to show the incomplete combustion of methane. [2]</li></ol>",["(a) 78 (%) (1).","(b) fractional (1) distillation (1).","(c) acid rain (1).","(d) Nitrogen and oxygen from the air react (1) at the high temperature in the engine (1).","(e) products: carbon dioxide (1) and nitrogen (1); catalyst: platinum (or rhodium / palladium) (1).","(f) 2CH~4~ + 3O~2~ → 2CO + 4H~2~O: correct formulae (1), correct balancing (1)."],X5_A(16)),
P("Incomplete combustion of butane",2,"<p>Write a chemical equation for the <b>incomplete</b> combustion of C~4~H~10~. [2]</p>",["2C~4~H~10~ + 9O~2~ → 8CO + 10H~2~O: correct formulae (1), correct balancing (1). Equations giving C or CO/C mixtures that balance are also accepted."],X5_A(17)),
P("Toxic product of incomplete combustion",1,"<p>A list of substances is shown.</p>"+X5_P19+"<p>State which substance is a toxic product of the incomplete combustion of hydrocarbons. [1]</p>",["carbon monoxide (1)."],X5_A(19)),
P("Process to separate liquid air",2,"<p>Nitrogen and oxygen can be separated from liquid air. State the name of this process. [2]</p>",["fractional (1) distillation (1)."],X5_A(20)),
P("Separating oxygen from liquid air",1,"<p>Give the name of the process that is used to separate oxygen from liquid air. [1]</p>",["fractional distillation (1)."],X5_A(22)),
P("Gas that causes acid rain",1,"<p>A list of substances is shown.</p>"+X5_P19+"<p>State which substance is a gas that causes acid rain. [1]</p>",["sulfur dioxide (1)."],X5_A(23)),
P("Percentage of nitrogen in air",1,"<p>Nitrogen, oxygen and other substances are found in clean, dry air. State the percentage of nitrogen in clean, dry air. [1]</p>",["78 (%) (1)."],X5_A(24)),
P("Another element in clean, dry air",1,"<p>Other than nitrogen and oxygen, identify another element found in clean, dry air. [1]</p>",["argon (or neon, helium, krypton, xenon) (1)."],X5_A(25)),
P("Air pollutants over four months",2,"<p>The table shows the mass of air pollutants, in nanograms, in 1000 cm<sup>3</sup> samples of air taken over a four month period.</p>"+TBL(["month","oxides of nitrogen","sulfur dioxide","carbon monoxide","ozone","particulates"],[["August","106.0","3.0","2.1","29.5","18.5"],["September","147.5","5.5","2.4","21.1","35.5"],["October","179.3","3.5","2.0","20.3","22.5"],["November","214.0","3.6","2.6","12.8","29.4"]],560)+"<p>Answer these questions using only the information in the table.</p><ol type='a'><li>Name the pollutant that shows a decrease in concentration between August and November. [1]</li><li>Calculate the mass of oxides of nitrogen in 250 cm<sup>3</sup> of the sample of air taken in August.<br>........ nanograms [1]</li></ol>",["(a) ozone (1).","(b) 106.0 × 250 / 1000 = 26.5 nanograms (1)."],X5_A(26))
);
